"      if (table.original_order_type === 'PRE_ORDER') {
        setOrderType('PRE_ORDER');
        setActiveTrayTab('PreOrder');
        setPreOrderSubTab(hasSavedBills ? 'BILLING' : 'KOT');
        if (table.pre_order_data) {
          setEditingPreOrder(table.pre_order_data);
          setCustomerName(table.pre_order_data.customer_name || '');
          setCustomerPhone(table.pre_order_data.customer_number || '');
          setCustomerAddress(table.pre_order_data.customer_address || '');
          setPreOrderScheduledDate(table.pre_order_data.scheduled_date || getCurrentDateString());
          setPreOrderScheduledTime(table.pre_order_data.scheduled_time || getCurrentTimeString());
          setPreOrderAdvanceAmount(String(table.pre_order_data.advance_paid || ''));
          setPreOrderNotes(table.pre_order_data.notes || '');
        } else {
          setEditingPreOrder(null);
        }
      }"
